import requests
from pathlib import Path
import zipfile

# Constants
DOWNLOAD_DIR = Path("downloads")
ZIP_DIR = Path("unzipped_files")

def task_func(url, filename):
    """
    Downloads a zip file from the given URL and extracts it.

    Args:
        url (str): The URL of the zip file to download.
        filename (str): The name to use for the downloaded zip file.

    Returns:
        tuple: (status_message, list_of_filenames)
               status_message (str): Description of success or error.
               list_of_filenames (list[str]): Filenames in the unzipped directory,
                                              or [] if extraction fails.
    """
    # Ensure directories exist
    try:
        DOWNLOAD_DIR.mkdir(parents=True, exist_ok=True)
        ZIP_DIR.mkdir(parents=True, exist_ok=True)
    except OSError as e:
        return (f"Error: Failed to create directories: {e}", [])

    zip_path = DOWNLOAD_DIR / filename

    # Download the file
    try:
        response = requests.get(url, stream=True, timeout=30)
        response.raise_for_status()
        with open(zip_path, "wb") as f:
            for chunk in response.iter_content(chunk_size=8192):
                if chunk:
                    f.write(chunk)
    except requests.exceptions.RequestException as e:
        return (f"Error: Failed to download file: {e}", [])
    except OSError as e:
        return (f"Error: Failed to write downloaded file: {e}", [])

    # Extract the zip file
    extracted_files = []
    try:
        with zipfile.ZipFile(zip_path, "r") as zip_ref:
            zip_ref.extractall(ZIP_DIR)
            for member in zip_ref.namelist():
                extracted_files.append(str(ZIP_DIR / member))
    except (zipfile.BadZipFile, zipfile.LargeZipFile, OSError) as e:
        return (f"Error: Failed to extract zip file: {e}", [])

    return ("Success: File downloaded and extracted.", extracted_files)

