import zipfile

# Constants
DOWNLOAD_DIR = Path("downloads")
ZIP_DIR = Path("unzipped_files")

def task_func(url, filename):
    """
    Downloads a zip file from the specified URL, saves it as `filename`
    in DOWNLOAD_DIR, and extracts its contents into ZIP_DIR.

    Args:
        url (str): The URL of the zip file to download.
        filename (str): The name to use for the downloaded zip file.

    Returns:
        tuple: (status_message, filenames_list)
            - status_message (str): A message describing the result.
              Contains "Error" if an error occurred.
            - filenames_list (list[str]): List of filenames in the
              unzipped directory, or an empty list if extraction fails.
    """
    # Ensure directories exist
    try:
        DOWNLOAD_DIR.mkdir(parents=True, exist_ok=True)
        ZIP_DIR.mkdir(parents=True, exist_ok=True)
    except Exception as e:
        return (f"Error: Failed to create directories: {e}", [])

    zip_path = DOWNLOAD_DIR / filename

    # Step 1: Download the file
    try:
        response = requests.get(url, stream=True, timeout=30)
        response.raise_for_status()
    except requests.exceptions.RequestException as e:
        return (f"Error: Failed to download file from {url}: {e}", [])

    # Step 2: Save the downloaded content to a file
    try:
        with open(zip_path, "wb") as f:
            for chunk in response.iter_content(chunk_size=8192):
                if chunk:  # filter out keep-alive chunks
                    f.write(chunk)
    except OSError as e:
        return (f"Error: Failed to write zip file to {zip_path}: {e}", [])

    # Step 3: Extract the zip file
    extracted_files = []
    try:
        with zipfile.ZipFile(zip_path, "r") as zip_ref:
            zip_ref.extractall(ZIP_DIR)

        # Collect list of filenames in the unzipped directory (recursive)
        for path in ZIP_DIR.rglob("*"):
            if path.is_file():
                # Store relative paths for clarity
                extracted_files.append(str(path.relative_to(ZIP_DIR)))

    except (zipfile.BadZipFile, OSError) as e:
        return (f"Error: Failed to extract zip file {zip_path}: {e}", [])

    status_message = f"Successfully downloaded and extracted to {ZIP_DIR}"
    return (status_message, extracted_files)

