from bs4 import BeautifulSoup

def task_func(url):
    dicts = []
    try:
        resp = requests.get(url, timeout=10)
        resp.raise_for_status()
    except Exception:
        return []

    try:
        soup = BeautifulSoup(resp.text, "html.parser")
    except Exception:
        return []

    scripts = soup.find_all("script")
    for script in scripts:
        # Get the textual content of the script tag
        text = script.string
        if not text:
            # Some script tags may not have .string, fallback to get_text
            text = script.get_text()
        if not text:
            continue

        # Try to find and evaluate dictionary-like substrings within the script
        # Approach: scan for top-level {...} blocks and try ast.literal_eval on each
        i = 0
        n = len(text)
        while i < n:
            # Find opening brace
            if text[i] != "{":
                i += 1
                continue

            # Track brace depth to find matching closing brace
            depth = 0
            start = i
            j = i
            while j < n:
                if text[j] == "{":
                    depth += 1
                elif text[j] == "}":
                    depth -= 1
                    if depth == 0:
                        # Candidate substring for dict
                        candidate = text[start:j+1].strip()
                        try:
                            obj = ast.literal_eval(candidate)
                            if isinstance(obj, dict):
                                dicts.append(obj)
                        except Exception:
                            pass
                        i = j  # move outer pointer to end of this block
                        break
                j += 1
            i += 1

    return dicts

