def task_func(url):
    results = []
    try:
        resp = requests.get(url, timeout=10)
        resp.raise_for_status()
    except Exception:
        return results  # empty list on request error

    soup = BeautifulSoup(resp.text, "html.parser")
    scripts = soup.find_all("script")

    for script in scripts:
        # Get the text content of the script tag
        content = script.string
        if not content:
            # If .string is None, try get_text()
            content = script.get_text()
        if not content:
            continue

        # Try to parse the entire script content as a Python literal
        try:
            parsed = ast.literal_eval(content.strip())
            if isinstance(parsed, dict):
                results.append(parsed)
        except Exception:
            # If that fails, try to find dictionary-like substrings
            # by scanning for top-level {...} blocks and evaluating them.
            text = content
            start = 0
            length = len(text)
            while True:
                brace_start = text.find("{", start)
                if brace_start == -1:
                    break
                # Track brace depth to find matching closing brace
                depth = 0
                i = brace_start
                end_idx = None
                while i < length:
                    ch = text[i]
                    if ch == "{":
                        depth += 1
                    elif ch == "}":
                        depth -= 1
                        if depth == 0:
                            end_idx = i
                            break
                    i += 1
                if end_idx is None:
                    break

                candidate = text[brace_start:end_idx + 1].strip()
                try:
                    parsed = ast.literal_eval(candidate)
                    if isinstance(parsed, dict):
                        results.append(parsed)
                except Exception:
                    pass

                start = end_idx + 1

    return results

