def task_func(myString, API_KEY):
    # Regex to extract URLs (http/https)
    url_pattern = re.compile(
        r'(https?://[^\s"\'>)]+)',
        re.IGNORECASE
    )
    urls = url_pattern.findall(myString)

    # Extract domains from URLs
    domains = set()
    for url in urls:
        parsed = urllib.parse.urlparse(url)
        if parsed.netloc:
            # Strip possible leading "www."
            domain = parsed.netloc.split('@')[-1]  # remove userinfo if present
            if ':' in domain:
                domain = domain.split(':')[0]       # remove port
            if domain.startswith('www.'):
                domain = domain[4:]
            if domain:
                domains.add(domain)

    results = {}

    # Call IP-API (https://ip-api.com/docs/api:json)
    # Using the API key via query parameter "key"
    # Example: http://ip-api.com/json/domain.com?key=API_KEY
    for domain in domains:
        try:
            resp = requests.get(
                f"http://ip-api.com/json/{domain}",
                params={"key": API_KEY},
                timeout=5
            )
            if resp.status_code == 200:
                data = resp.json()
                # If the API itself signals failure, store None
                if isinstance(data, dict) and data.get("status") == "success":
                    results[domain] = data
                else:
                    results[domain] = None
            else:
                results[domain] = None
        except Exception:
            results[domain] = None

    return results

