    url_pattern = re.compile(
        r'(?i)\b((?:https?://|ftp://|www\.)[^\s<>"\'()]+)'
    )

    urls = url_pattern.findall(myString)

    # Normalize URLs and extract domains
    domains = set()
    for url in urls:
        # Ensure scheme for URLs starting with www.
        if url.lower().startswith("www."):
            url = "http://" + url
        try:
            parsed = urllib.parse.urlparse(url)
            host = parsed.netloc.split(":")[0]  # strip port
            if host:
                domains.add(host.lower())
        except Exception:
