def task_func(data_url: str) -> list:
    try:
        resp = requests.get(data_url)
        text = resp.text
    except Exception:
        return ["Invalid url input"]

    # Try to load as JSON; if it fails, treat as plain text
    try:
        data = json.loads(text)
        # Convert JSON back to a nicely formatted string for regex processing
        text = json.dumps(data)
    except Exception:
        pass

    # Remove all content inside square brackets (including nested brackets)
    # This prevents extracting names that are inside square brackets
    def remove_brackets(s: str) -> str:
        result = []
        level = 0
        for ch in s:
            if ch == '[':
                level += 1
            elif ch == ']':
                level = max(0, level - 1)
            elif level == 0:
                result.append(ch)
        return ''.join(result)

    cleaned_text = remove_brackets(text)

    # Regex to find "name":"Some Name" or 'name': 'Some Name' etc.
    # Handles keys named "name" (case-insensitive) and captures the value.
    pattern = re.compile(
        r'(?i)"name"\s*:\s*"([^"]+)"|'
        r"(?i)'name'\s*:\s*'([^']+)'"
    )

    names = []
    for match in pattern.finditer(cleaned_text):
        # match.group(1) for double-quoted, group(2) for single-quoted
        val = match.group(1) if match.group(1) is not None else match.group(2)
        if val is not None:
            names.append(val)

    return names

