import unicodedata
import requests

URL = 'https://api.github.com/users/'

def task_func(username):
    """
    Retrieves user information from the GitHub API for a given username,
    normalizes all string data to ASCII, and returns a dictionary of the
    normalized data.

    Raises:
        requests.exceptions.HTTPError: For any HTTP response indicating an error.

    Returns:
        dict: A dictionary with the user's data, where all string values are
              normalized to ASCII.
    """
    def normalize_value(value):
        """
        Recursively normalize all string values in a structure (dict, list, etc.)
        to ASCII, ignoring characters that cannot be converted.
        """
        if isinstance(value, str):
            # Normalize Unicode to NFKD then encode to ASCII, ignoring errors
            normalized = unicodedata.normalize("NFKD", value)
            return normalized.encode("ascii", "ignore").decode("ascii")
        elif isinstance(value, list):
            return [normalize_value(item) for item in value]
        elif isinstance(value, dict):
            return {normalize_value(k): normalize_value(v) for k, v in value.items()}
        else:
            # Non-string scalars are returned as-is (int, float, bool, None, etc.)
            return value

    response = requests.get(URL + username)
    # Raise HTTPError for any HTTP error response (4xx, 5xx)
    response.raise_for_status()

    data = response.json()
    # Ensure the top-level result is a dict and normalize its contents
    if isinstance(data, dict):
        return normalize_value(data)
    else:
        # If GitHub ever returns a non-dict, still normalize generically
        return normalize_value(data)

